import React from "react"


function About(){
    return(

        <div className="d-flex justify-content-center align-items-center">

            {/* <div className="mx-auto text-center my-5 py-5">
                <img src={"./about.jpg"} className="img-fluid object-fit-cover w-50 p-1 about-img "  alt="Aboutpage" />
            </div> */}

            <div className="overlap-container">
                {/* Card 1: Base position, sits behind */}
                <div className="card overlap-card-1">
                    <h3>Card One</h3>
                    <p>This card will sit at the bottom layer.</p>
                </div>

                {/* Card 2: Shifted position, sits on top */}
                <div className="card overlap-card-2">
                    <h3>Card Two</h3>
                    <p>This card will overlap Card One.</p>
                </div>
            </div>
        </div>
    )
}

export default About
